import sys

data = sys.stdin.read().split()
n, m, s, t = int(data[0]), int(data[1]), int(data[2]), int(data[3])
INF = 10**9
D = [[INF] * n for _ in range(n)]
for i in range(n):
    D[i][i] = 0
adj = [[] for _ in range(n)]
for i in range(m):
    u = int(data[4 + 2 * i]); v = int(data[5 + 2 * i])
    D[u][v] = D[v][u] = 1
    adj[u].append(v)
    adj[v].append(u)
for k in range(n):
    for i in range(n):
        for j in range(n):
            if D[i][k] + D[k][j] < D[i][j]:
                D[i][j] = D[i][k] + D[k][j]
if D[s][t] >= INF:
    print(-1)
else:
    paths = []
    def rec(u, path):
        if u == t:
            paths.append(list(path))
            return
        for v in adj[u]:
            if D[s][u] + 1 + D[v][t] == D[s][t] and D[s][v] == D[s][u] + 1:
                path.append(v)
                rec(v, path)
                path.pop()
    rec(s, [s])
    best = min(paths)
    print(D[s][t])
    print(' '.join(map(str, best)))

